-- Módulo 65 VacacionesPermisos: solicitudes de vacaciones, permisos y licencias de los empleados.
-- Spec: docs/specs/modulo65-vacaciones-permisos-backend.md (§4).

CREATE TABLE "Ausencias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Tipo" character varying(30) NOT NULL,
    "FechaInicio" date NOT NULL,
    "FechaFin" date NOT NULL,
    "Dias" integer NOT NULL,
    "Motivo" character varying(300),
    "Estado" character varying(20) NOT NULL,
    "FechaSolicitud" date NOT NULL,
    "DecididoPor" character varying(100),
    "FechaDecision" timestamp with time zone,
    "MotivoRechazo" character varying(300),
    "FechaCancelacion" date,
    CONSTRAINT "PK_Ausencias" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Ausencias_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Ausencias_Tipo" CHECK ("Tipo" IN ('Vacaciones', 'PermisoConGoce', 'PermisoSinGoce', 'LicenciaMaternidad', 'LicenciaPaternidad', 'DescansoMedico')),
    CONSTRAINT "CK_Ausencias_Estado" CHECK ("Estado" IN ('Pendiente', 'Aprobada', 'Rechazada', 'Cancelada')),
    CONSTRAINT "CK_Ausencias_Fechas" CHECK ("FechaFin" >= "FechaInicio")
);
CREATE UNIQUE INDEX "IX_Ausencias_Numero" ON "Ausencias" ("Numero");
CREATE INDEX "IX_Ausencias_EmpleadoId_FechaInicio" ON "Ausencias" ("EmpleadoId", "FechaInicio");
